<?php
namespace App\Http\Controllers\Audit; use App\Http\Controllers\Controller; use App\Models\ActivityLog; use App\Models\User; use Illuminate\Http\Request;
class ActivityLogController extends Controller { public function __construct(){ $this->middleware('menu.permission:audit.activity-log,view'); } public function index(Request $request){$q=ActivityLog::with('user')->latest('created_at');foreach(['module','action','document_number'] as $f)if($request->filled($f))$q->where($f,'like','%'.$request->input($f).'%');if($request->filled('user_id'))$q->where('user_id',$request->integer('user_id'));if($request->filled('date_from'))$q->whereDate('created_at','>=',$request->date('date_from'));if($request->filled('date_to'))$q->whereDate('created_at','<=',$request->date('date_to'));return view('audit.activity-log.index',['rows'=>$q->paginate(50)->withQueryString(),'users'=>User::orderBy('name')->pluck('name','id')]);} }
